private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (bb == null || sb == null) {
        return i;
    }
    int startPos = bb.position();
    int remaining = bb.remaining();
    if (remaining == 0) {
        return i;
    }
    // Create a read-only slice that shares the bytes but does not modify the original buffer's position
    ByteBuffer slice = bb.slice();
    CharBuffer charBuffer;
    try {
        charBuffer = java.nio.charset.StandardCharsets.UTF_8.decode(slice);
    } catch (java.nio.charset.CharacterCodingException e) {
        throw new IllegalArgumentException("Invalid UTF-8 byte sequence at position " + startPos, e);
    }
    sb.append(charBuffer);
    // Advance the original ByteBuffer's position past the consumed bytes
    bb.position(startPos + remaining);
    return i + remaining;
