private void enlarge(final int size){
    // Return if no additional space is required
    if (size <= 0){
        return;
    }
    // Prevent integer overflow in calculation of new capacity
    if (size > Integer.MAX_VALUE - data.length){
        throw new IllegalArgumentException("Requested size is too large");
    }
    // Double current capacity or grow enough to fit the requested size
    int newCapacity = Math.max(data.length * 2, data.length + size);
    byte[] newData = new byte[newCapacity];
    try{
        System.arraycopy(data, 0, newData, 0, length);
    }catch(ArrayIndexOutOfBoundsException | NullPointerException e){
        throw new RuntimeException("Failed to enlarge byte vector", e);
    }
    data = newData;
