        for(int i=0;i<rightSize;i++){
            String id = "R"+i;
            V v = target.addVertex(id);
            resultMap.put(id, v);
        }
        // Add all edges between left and right partitions
        for(String lid : resultMap.keySet()){
            if(!lid.startsWith("L")) continue;
            V left = resultMap.get(lid);
            for(String rid : resultMap.keySet()){
                if(!rid.startsWith("R")) continue;
                V right = resultMap.get(rid);
                // Assume target.addEdge(V, V) exists
                target.addEdge(left, right);
