public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new NullPointerException("OutputStream is null");
    }
    if (schema == null) {
        throw new NullPointerException("Schema is null");
    }
    if (message == null) {
        throw new NullPointerException("Message is null");
    }
    // Compute the size of the serialized message
    int size;
    try {
        size = schema.getMessageSize(message);
    } catch (Exception e) {
        throw new IOException("Failed to compute message size", e);
    }
    // Write the size as a varint prefix
    writeVarint32(out, size);
    // Serialize the message
    try {
        // If a LinkedBuffer is provided, use it for encoding to reduce allocations
        if (buffer != null) {
            schema.encode(message, buffer);
            // Write the encoded bytes from the buffer
            byte[] bytes = buffer.toByteArray();
            out.write(bytes, 0, size);
        } else {
            // Fallback: use the schema's writeTo method
            schema.writeTo(message, out);
        }
    } catch (Exception e) {
        throw new IOException("Failed to serialize message", e);
    }
    return size;
}

private static void writeVarint32(OutputStream out, int value) throws IOException {
    while ((value & 0xFFFFFF80) != 0) {
        out.write((value & 0x7F) | 0x80);
        value >>>= 7;
    }
    out.write(value);
