public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) {
        return null;
    }
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType genericParam = (ParameterizedType) genericType;
    Type targetGeneric = findMatchingGeneric(targetType, genericParam.getRawType());
    if (targetGeneric == null) {
        return null;
    }

    try {
        if (targetGeneric instanceof ParameterizedType) {
            ParameterizedType pt = (ParameterizedType) targetGeneric;
            Type[] actualArgs = pt.getActualTypeArguments();
            Class<?>[] result = new Class<?>[actualArgs.length];
            for (int i = 0; i < actualArgs.length; i++) {
                result[i] = toRawClass(actualArgs[i]);
                if (result[i] == null) {
                    // Could not resolve this particular argument
                    return null;
                }
            }
            return result;
        } else if (targetGeneric instanceof Class<?>) {
            // No generics to resolve
            return new Class<?>[0];
        } else {
            return null;
        }
    } catch (Exception e) {
        // In case of any runtime reflection issues, return null
        return null;
    }
}

private static Type findMatchingGeneric(Class<?> cls, Type rawType) {
    // Check superclass
    Type superGen = cls.getGenericSuperclass();
    if (superGen != null) {
        if (matchesRaw(superGen, rawType)) {
            return superGen;
        }
        if (superGen instanceof Class<?>) {
            Type result = findMatchingGeneric((Class<?>) superGen, rawType);
            if (result != null) {
                return result;
            }
        } else {
            Type result = findMatchingGeneric((Class<?>) ((ParameterizedType) superGen).getRawType(), rawType);
            if (result != null) {
                return result;
            }
        }
    }

    // Check interfaces
    for (Type iface : cls.getGenericInterfaces()) {
        if (matchesRaw(iface, rawType)) {
            return iface;
        }
        if (iface instanceof Class<?>) {
            Type result = findMatchingGeneric((Class<?>) iface, rawType);
            if (result != null) {
                return result;
            }
        } else if (iface instanceof ParameterizedType) {
            Type result = findMatchingGeneric((Class<?>) ((ParameterizedType) iface).getRawType(), rawType);
            if (result != null) {
                return result;
            }
        }
    }

    // No match found
    return null;
}

private static boolean matchesRaw(Type type, Type rawType) {
    if (type == null || rawType == null) {
        return false;
    }
    if (type instanceof ParameterizedType) {
        return ((ParameterizedType) type).getRawType().equals(rawType);
    }
    return type.equals(rawType);
}

private static Class<?> toRawClass(Type t) {
    if (t instanceof Class<?>) {
        return (Class<?>) t;
    }
    if (t instanceof ParameterizedType) {
        Type raw = ((ParameterizedType) t).getRawType();
        return raw instanceof Class<?> ? (Class<?>) raw : null;
    }
    if (t instanceof GenericArrayType) {
        Class<?> component = toRawClass(((GenericArrayType) t).getGenericComponentType());
        return component != null ? java.lang.reflect.Array.newInstance(component, 0).getClass() : null;
    }
    // For TypeVariable or WildcardType, attempt to use the upper bound
    if (t instanceof TypeVariable<?>) {
        TypeVariable<?> var = (TypeVariable<?>) t;
        Type[] bounds = var.getBounds();
        if (bounds.length > 0) {
            return toRawClass(bounds[0]);
        }
    }
    if (t instanceof WildcardType) {
        WildcardType wt = (WildcardType) t;
        Type[] bounds = wt.getUpperBounds();
        if (bounds.length > 0) {
            return toRawClass(bounds[0]);
        }
    }
    return null;
