    // Existing history mapping provided as 'mappings'.
    Map<String, Object> historyProps = null;
    Map<String, Object> currentProps = null;
    try {
        if (mappings != null) {
            // Assume Mappings has a method getProperties() returning a map of field name to definition.
            historyProps = mappings.getProperties();
        }
        // Retrieve current mapping for the table.  In a real implementation this would
        // query Elasticsearch or a configuration store; here we just call a helper
        // method that should be provided by the surrounding class.
