    if (currentProps == null) {
        return new Mappings(); // nothing to diff with
    }
    Map<String, Object> diff = new LinkedHashMap<>();
    for (Map.Entry<String, Object> entry : currentProps.entrySet()) {
        String field = entry.getKey();
        // Skip the _source field to avoid update conflicts.
        if ("_source".equals(field)) {
            continue;
        }
        Object currentDef = entry.getValue();
        Object historyDef = historyProps != null ? historyProps.get(field) : null;
        if (historyDef == null) {
            // Field does not exist in history, include it in the diff.
            diff.put(field, currentDef);
        } else {
            // If the definitions differ, also include it.
            try {
                if (!currentDef.equals(historyDef)) {
                    diff.put(field, currentDef);
                }
            } catch (Exception ex) {
                // If equality check fails, conservatively add the field.
                diff.put(field, currentDef);
            }
        }
    }
    Mappings result = new Mappings();
    result.setProperties(diff);
    return result;
