static long compressTimeBucket(long timeBucket,int dayStep){
    if (dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be positive");
    }
    int year = (int)(timeBucket / 10000);
    int monthDay = (int)(timeBucket % 10000);
    int month = monthDay / 100;
    int day = monthDay % 100;
    if (year <= 0 || month < 1 || month > 12 || day < 1 || day > 31){
        throw new IllegalArgumentException("Invalid timeBucket format: " + timeBucket);
    }
    int bucketStartDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000L + month * 100L + bucketStartDay;
}<|return|>

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if (str == null || len <= 0 || index < 0) {
        return 0;
    }
    if (index > str.length()) {
        return 0;
    }
    int maxEnd = Math.min(str.length(), index + len);
    int bytes = 0;
    int i = index;
    try {
        while (i < maxEnd) {
            int codePoint = str.codePointAt(i);
            if (codePoint <= 0x7F) {
                bytes += 1;
            } else if (codePoint <= 0x7FF) {
                bytes += 2;
            } else if (codePoint <= 0xFFFF) {
                bytes += 3;
            } else {
                bytes += 4;
            }
            i += Character.charCount(codePoint);
        }
    } catch (IndexOutOfBoundsException e) {
        // In case of malformed input, return 0
        return 0;
    }
    return bytes;
}<|return|>

