    List<PathSegmentImpl> result = new ArrayList<>();
    if (path == null || path.isEmpty()) {
        return result;
    }
    // Split on '/' but keep empty segments if any
    String[] parts = path.split("/", -1);
    for (String part : parts) {
        // skip the leading empty segment for absolute paths
        if (part.isEmpty() && path.startsWith("/")) {
            continue;
        }
        String seg = part;
        if (decode) {
            try {
                seg = java.net.URLDecoder.decode(seg, java.nio.charset.StandardCharsets.UTF_8.name());
