protected int removeUnusedNodes(){
    int removedCount = 0;
    try {
        if (root == null) {
            return 0;
        }
        java.util.Deque<Category> stack = new java.util.ArrayDeque<>();
        java.util.Map<Category, Category> parentMap = new java.util.HashMap<>();
        stack.push(root);
        parentMap.put(root, null);
        java.util.List<Category> order = new java.util.ArrayList<>();
        while (!stack.isEmpty()) {
            Category current = stack.pop();
            order.add(current);
            java.util.List<Category> children = current.getChildren();
            if (children != null) {
                for (Category child : children) {
                    stack.push(child);
                    parentMap.put(child, current);
                }
            }
        }
        java.util.Collections.reverse(order);
        for (Category node : order) {
            if (!node.isActive()) {
                Category parent = parentMap.get(node);
                if (parent != null) {
                    parent.removeChild(node);
                } else {
                    // Node is root
                    root = null;
                }
                removedCount++;
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Error while removing unused nodes from Category tree", e);
    }
    return removedCount;
