private void pop(final String descriptor){
    int count = 0;
    try {
        if (descriptor == null || descriptor.isEmpty()) {
            return;
        }
        int i = 0;
        if (descriptor.charAt(0) == '(') {          // method descriptor: pop only argument types
            i = 1;
            while (i < descriptor.length() && descriptor.charAt(i) != ')') {
                char c = descriptor.charAt(i);
                if (c == '[') {                     // array type
                    while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                        i++;
                    }
                    if (i < descriptor.length()) {
                        i++;                         // skip base type char
                        count++;                     // array occupies one slot (base type is counted when processing base type)
                    }
                } else if (c == 'L') {              // object type
                    i++;
                    while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                        i++;
                    }
                    i++;                             // skip ';'
                    count++;                         // object occupies one slot
                } else if (c == 'J' || c == 'D') {  // long or double occupy two slots
                    count += 2;
                    i++;
                } else {                            // all other primitive types occupy one slot
                    count++;
                    i++;
                }
            }
        } else {                                     // single type descriptor
            while (i < descriptor.length()) {
                char c = descriptor.charAt(i);
                if (c == '[') {
                    while (i < descriptor.length() && descriptor.charAt(i) == '[') {
                        i++;
                    }
                    if (i < descriptor.length()) {
                        i++;                             // skip base type char
                        count++;                         // array occupies one slot
                    }
                } else if (c == 'L') {
                    i++;
                    while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                        i++;
                    }
                    i++;                                 // skip ';'
                    count++;                             // object occupies one slot
                } else if (c == 'J' || c == 'D') {
                    count += 2;                           // long or double occupy two slots
                    i++;
                } else {
                    count++;                               // other primitive types occupy one slot
                    i++;
                }
            }
        }
        // decrement the stack pointer; this code assumes a field named 'pos' holds the current stack top index.
        pos -= count;
        if (pos < 0) {
            throw new RuntimeException("stack underflow while popping descriptor '" + descriptor + "'");
        }
    } catch (RuntimeException e) {
        throw e;              // re‑throw to preserve stack trace
    } catch (Exception e) {
        throw new RuntimeException("unexpected error while popping descriptor '" + descriptor + "'", e);
    }
