private java.util.List<Integer> computeUpperBounds(java.util.List<K> keys){
    java.util.List<Integer> bounds = new java.util.ArrayList<>();
    if (keys == null) {
        return bounds;
    }
    java.util.List<Integer> intKeys = new java.util.ArrayList<>();
    for (K k : keys) {
        if (k instanceof Integer) {
            intKeys.add((Integer)k);
        }
    }
    java.util.List<Integer> sorted = new java.util.ArrayList<>(intKeys);
    java.util.Collections.sort(sorted);
    for (K k : keys) {
        if (k == null || !(k instanceof Integer)) {
            bounds.add(null);
            continue;
        }
        int keyVal = (Integer)k;
        int idx = java.util.Collections.binarySearch(sorted, keyVal);
        if (idx < 0) {
            idx = -(idx + 1);
        }
        if (idx < sorted.size()) {
            bounds.add(sorted.get(idx));
        } else {
            bounds.add(Integer.MAX_VALUE);
        }
    }
    return bounds;
}<|return|>

