public static String applyRelativePath(String path,String relativePath){
    try{
        if(path==null) path="";
        if(relativePath==null) relativePath="";
        java.nio.file.Path base = java.nio.file.Paths.get(path);
        java.nio.file.Path resolved = base.resolve(relativePath).normalize();
        String sep = java.io.File.separator;
        if(!"/".equals(sep)){
            return resolved.toString().replace(sep,"/");
        }else{
            return resolved.toString();
        }
    }catch(Exception e){
        try{
            boolean leading = path.startsWith("/");
            java.util.LinkedList<String> stack = new java.util.LinkedList<>();
            for(String part: path.split("/")){
                if(part.isEmpty()||part.equals(".")) continue;
                stack.addLast(part);
            }
            for(String part: relativePath.split("/")){
                if(part.isEmpty()||part.equals(".")) continue;
                if(part.equals("..")){
                    if(!stack.isEmpty()){
                        stack.removeLast();
                    }
                }else{
                    stack.addLast(part);
                }
            }
            StringBuilder sb = new StringBuilder();
            if(leading) sb.append("/");
            java.util.Iterator<String> it = stack.iterator();
            while(it.hasNext()){
                sb.append(it.next());
                if(it.hasNext()) sb.append("/");
            }
            return sb.toString();
        }catch(Exception ex){
            return path;
        }
    }
