                            start = range.getStartTime();
                            end = range.getEndTime();
                        } catch (Exception e) {
                            // If range methods unavailable, skip this range
                            continue;
                        }
                        if (tsTime >= start && tsTime <= end) {
                            result.add(ts);
                            break;
                        }
                    }
                }
            }
        }
    } catch (ClassNotFoundException cnf) {
        throw new IOException("Failed to deserialize objects from file", cnf);
    }
    return result;
}
